List<int> parseMusic(String music) {
  RegExp pattern = new RegExp(r'[o.]|\||\s');

  List<String> tokens = <String>[];
  for (Match match in pattern.allMatches(music)) 
    if (!match.group(0).isBlank)
      // Filter out empty strings from split method.
      tokens.add(match[1] ?? '');

  int lastLength = -2;   /* initial value makes it different than anything else */

  return listMap(tokens,
                 (_) => (_ == '.' || _ == '|') ? ++lastLength : --lastLength);
}
