String fixSpaces(String text) {
  String newText = "";
  int i = 0;
  int start = 0;
  int end = 0;

  while (i < text.length) {
    if (text[i] == " ") {
      end += 1;
    } else {
      if (end - start > 2) {
        newText += "-" + text[i];
      } else if (end - start > 0) {
